from pathlib import Path

from django.conf import settings
from django.core.files import File
from django.core.management.base import BaseCommand
from django.utils import timezone

from core.models import NewsArticle


TITLE = 'Знакомство с автомобилем: от первого вопроса до тест-драйва'
BODY = '\n\n'.join([
    'Знакомство с автомобилем начинается задолго до поворота ключа. В CarShowroom мы предлагаем сначала обсудить, для каких поездок нужна машина: ежедневного маршрута по городу, семейных путешествий или рабочих встреч. Такой разговор помогает сравнивать не только внешний вид, но и особенности разных моделей. Посетитель может заранее составить список вопросов и вернуться к нему после осмотра.',
    'В выставочном зале удобно рассмотреть несколько автомобилей рядом. У каждой модели свой характер: отличаются размеры кузова, форма дверных проёмов, организация багажника и обзор с водительского места. Сотрудник салона показывает доступные комплектации и объясняет обозначения в карточке автомобиля. При этом окончательный выбор остаётся за покупателем, а знакомство не обязывает оформлять заказ.',
    'Отдельная часть встречи посвящена салону. Посетитель может оценить расположение органов управления, пространство на втором ряду и удобство посадки. Важно не торопиться: впечатление от фотографии нередко отличается от ощущения внутри автомобиля. Если машиной будут пользоваться несколько членов семьи, обсудить их ожидания полезно ещё на этапе знакомства с моделью.',
    'Затем можно перейти к оснащению. В каталоге представлены сведения о годе выпуска, типе топлива, категории и стоимости автомобиля. Эти данные служат отправной точкой для разговора с консультантом. Он уточняет комплектацию конкретного экземпляра и отвечает на вопросы об установленных системах. Сведения о разных машинах лучше сравнивать по одинаковому набору характеристик.',
    'Тест-драйв позволяет дополнить знакомство личными впечатлениями. Время и условия пробной поездки согласовываются с сотрудником салона. Перед началом посетителю показывают основные органы управления и рассказывают о порядке проведения встречи. Во время знакомства можно обратить внимание на обзорность, удобство сиденья и восприятие габаритов, а вопросы обсудить с сопровождающим сотрудником.',
    'После поездки полезно вернуться к первоначальному списку ожиданий. Одни особенности становятся заметнее в движении, другие проще оценить на стоянке. Покупатель может сравнить впечатления от нескольких моделей, уточнить интересующие детали и спокойно обдумать результат. Консультант помогает собрать информацию, не подменяя личный выбор клиента.',
    'На сайте CarShowroom знакомство можно продолжить дома. Карточки каталога позволяют ещё раз посмотреть основные характеристики, новости рассказывают о событиях салона, а страница контактов помогает найти нужного сотрудника. Если понравилось несколько вариантов, удобно выписать их названия перед следующим визитом. Так обсуждение получится предметным и последовательным.',
    'Мы рассматриваем знакомство с автомобилем как диалог. Хорошая встреча заканчивается не обязательно покупкой, а понятными ответами на вопросы. Можно договориться о повторном визите, посмотреть другую комплектацию или вернуться к выбору позже. Наша задача — сделать информацию доступной, а общение с автосалоном понятным на каждом этапе.',
])


class Command(BaseCommand):
    help = 'Добавляет одну развёрнутую статью, не изменяя существующие новости.'

    def handle(self, *args, **options):
        article, created = NewsArticle.objects.get_or_create(
            title=TITLE,
            defaults={
                'summary': 'Рассказываем, как проходит знакомство с автомобилем в CarShowroom и какие вопросы можно обсудить с консультантом.',
                'body': BODY,
                'published_at': timezone.now(),
                'is_published': True,
            },
        )
        if created:
            image_path = Path(settings.BASE_DIR) / 'core/static/core/img/banner-test-drive.png'
            with image_path.open('rb') as source:
                article.image.save('showroom-test-drive.png', File(source))
        self.stdout.write('Статья добавлена.' if created else 'Статья уже существует; данные не изменены.')
